#pragma once
#include "StockFinalDynamicsTests.h"
#define createPluginFilter createPlateTestFilter
#include "../plugins/TracksmithPlate/PlateProcessor.cpp"
#undef createPluginFilter
#define createPluginFilter createDelayTestFilter
#include "../plugins/TracksmithDelay/DelayProcessor.cpp"
#undef createPluginFilter
#include <vector>
inline int runDelayTests(const char* path,const char* preview){using namespace TracksmithDelay;Engine e;e.prepare(48000);Settings s;s.time=100;s.feedback=50;s.mix=100;float l[256]{},r[256]{};float* ch[]{l,r};for(int b=0;b<100;++b)e.process(ch,2,256,s);std::vector<float> response(16000);for(int b=0;b<64;++b){std::fill_n(l,256,0);std::fill_n(r,256,0);if(b==0)l[0]=1;e.process(ch,2,256,s);for(int n=0;n<256&&b*256+n<16000;++n){response[size_t(b*256+n)]=l[n];dynamicsCheck(r[n]==0,"delay channels isolated");}}
 dynamicsCheck(std::abs(response[4800]-1)<.001,"first repeat exactly 100ms");dynamicsCheck(response[9600]>.4f&&response[9600]<.51f,"feedback repeat attenuates");dynamicsCheck(std::abs(response[4799])<1.e-6f&&std::abs(response[4801])<1.e-6f,"no static-time modulation spread");e.reset();std::fill_n(l,256,0);std::fill_n(r,256,0);e.process(ch,2,256,s);dynamicsCheck(l[255]==0,"delay reset clears tail");
 for(double rate:{8000.,44100.,48000.,96000.,192000.}){e.prepare(rate);for(int b=0;b<300;++b){s.time=float(1+b%2000);s.feedback=90;s.lowpass=float(1000+b%17000);s.mix=100;for(int n=0;n<256;++n){l[n]=.01f*float(std::sin((b*256+n)*.17));r[n]=0;}e.process(ch,2,256,s);for(float value:l)dynamicsCheck(std::isfinite(value)&&std::abs(value)<1,"delay extreme settings bounded");}s.bypass=true;for(int b=0;b<20;++b){std::fill_n(l,256,.1f);e.process(ch,1,256,s);}dynamicsCheck(std::abs(l[255]-.1f)<1.e-6,"delay bypass unity");s.bypass=false;}
 std::cout<<"PASS: digital delay repeat timing, feedback decay, channel isolation, static-time impulse, reset, parameter changes, bypass and 5 sample rates\n";return stockDynamicsHost<DelayProcessor>(path,preview);}
inline int runPlateTests(const char* path,const char* preview){using namespace TracksmithPlate;auto impulse=[](float decay,float predelay,float width){Engine e;e.prepare(48000);Settings s;s.decay=decay;s.predelay=predelay;s.width=width;s.mix=100;s.damping=18000;s.lowcut=20;float l[256]{},r[256]{};float* ch[]{l,r};for(int b=0;b<100;++b)e.process(ch,2,256,s);std::vector<float> data(96000*2);for(int b=0;b<375;++b){std::fill_n(l,256,0);std::fill_n(r,256,0);if(b==0)l[0]=r[0]=1;e.process(ch,2,256,s);for(int n=0;n<256;++n){data[size_t(2*(b*256+n))]=l[n];data[size_t(2*(b*256+n)+1)]=r[n];}}return data;};auto shortTail=impulse(1,0,100),longTail=impulse(3,0,100),pre=impulse(3,100,100),mono=impulse(3,0,0);
 auto onset=[](const std::vector<float>& x){for(size_t n=0;n<x.size()/2;++n)if(std::abs(x[n*2])+std::abs(x[n*2+1])>1.e-6)return int(n);return -1;};dynamicsCheck(std::abs(onset(pre)-onset(longTail)-4800)<3,"plate predelay shifts wet onset");double a=0,b=0,difference=0;int dense=0;for(int n=4800;n<96000;++n){float l=longTail[size_t(n*2)],r=longTail[size_t(n*2+1)];dynamicsCheck(std::isfinite(l)&&std::isfinite(r),"finite plate tail");if(n>48000){a+=shortTail[size_t(n*2)]*shortTail[size_t(n*2)];b+=l*l;}if(n<24000&&std::abs(l)>1.e-9)++dense;difference+=std::abs(l-r);dynamicsCheck(std::abs(mono[size_t(n*2)]-mono[size_t(n*2+1)])<1.e-7,"zero width mono wet");}dynamicsCheck(b>a*5,"long decay sustains more tail energy");dynamicsCheck(dense>15000,"plate dense diffuse tail");dynamicsCheck(difference>.01,"stereo decorrelation");
 for(double rate:{8000.,44100.,48000.,96000.,192000.}){Engine e;e.prepare(rate);Settings s;s.decay=10;s.mix=100;float l[256]{},r[256]{};float* ch[]{l,r};for(int block=0;block<500;++block){s.predelay=float(block%201);s.damping=float(1000+block%17000);for(int n=0;n<256;++n){l[n]=.01f*float(std::sin((block*256+n)*.13));r[n]=l[n];}e.process(ch,2,256,s);for(float value:l)dynamicsCheck(std::isfinite(value)&&std::abs(value)<1,"plate extreme settings bounded");}e.reset();std::fill_n(l,256,0);std::fill_n(r,256,0);e.process(ch,2,256,s);dynamicsCheck(l[255]==0&&r[255]==0,"plate reset clears tail");s.bypass=true;for(int block=0;block<20;++block){std::fill_n(l,256,.1f);e.process(ch,1,256,s);}dynamicsCheck(std::abs(l[255]-.1f)<1.e-6,"plate bypass unity");}
 std::cout<<"PASS: plate predelay, decay-energy ordering, diffuse tail density, stereo width, reset, bounded parameter changes, bypass and 5 sample rates\n";return stockDynamicsHost<PlateProcessor>(path,preview);}
